+			break;
+		case 13:
+			TH_LOG("child exit 13: socket failed with unexpected errno (want ENOSYS)");
+			break;
+		default:
+			TH_LOG("child exit %d (unexpected)", WEXITSTATUS(status));
+		}
+	}
